import sys
from collections import defaultdict, deque

MOD = 1000000007

def bfs(graph, start, end, parent):
    visited = [False] * (len(graph) + 1)
    queue = deque([start])
    visited[start] = True
    while queue:
        node = queue.popleft()
        if node == end:
            return True
        for neighbor in graph[node]:
            if not visited[neighbor]:
                visited[neighbor] = True
                parent[neighbor] = node
                queue.append(neighbor)
    return False

def find_path(parent, start, end):
    path = []
    while end != -1:
        path.append(end)
        end = parent[end]
    path.reverse()
    return path

def count_paths(graph, start, end, cycles, memo):
    if (start, end) in memo:
        return memo[(start, end)]
    if start == end:
        return 1
    count = 0
    for neighbor in graph[start]:
        if neighbor not in cycles:
            count += count_paths(graph, neighbor, end, cycles, memo)
            count %= MOD
    memo[(start, end)] = count
    return count

def main():
    import sys
    input = sys.stdin.read().split()
    index = 0
    n = int(input[index])
    m = int(input[index + 1])
    index += 2
    graph = defaultdict(list)
    for _ in range(m):
        a = int(input[index])
        b = int(input[index + 1])
        graph[a].append(b)
        graph[b].append(a)
        index += 2
    k = int(input[index])
    index += 1
    queries = []
    for _ in range(k):
        x = int(input[index])
        y = int(input[index + 1])
        queries.append((x, y))
        index += 2

    visited = [False] * (n + 1)
    cycles = set()
    for node in range(1, n + 1):
        if not visited[node]:
            stack = [(node, -1)]
            parent = {}
            while stack:
                current, prev = stack.pop()
                if visited[current]:
                    if prev != parent[current]:
                        cycle_node = current
                        cycle = []
                        while cycle_node != prev:
                            cycle.append(cycle_node)
                            cycle_node = parent[cycle_node]
                        cycle.append(prev)
                        cycles.update(cycle)
                    continue
                visited[current] = True
                parent[current] = prev
                for neighbor in graph[current]:
                    if neighbor != prev:
                        stack.append((neighbor, current))

    results = []
    for x, y in queries:
        parent = [-1] * (n + 1)
        if bfs(graph, x, y, parent):
            path = find_path(parent, x, y)
            path_set = set(path)
            new_graph = {node: [neighbor for neighbor in graph[node] if neighbor not in path_set] for node in range(1, n + 1)}
            count = count_paths(new_graph, x, y, cycles, {})
            results.append(count % MOD)
        else:
            results.append(0)

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
